import torch
import torch.nn as nn
import hashlib
from torch.utils.cpp_extension import load_inline

_STARK_EXTENSION = None

def _stark_strip_anchor_markers(source: str) -> str:
    cleaned_lines = []
    for line in source.splitlines():
        stripped = line.lstrip()
        if stripped.startswith('# <<<IMPROVE:') or stripped.startswith('# <<<END_IMPROVE>>>'):
            continue
        cleaned_lines.append(line)
    return '\n'.join(cleaned_lines)

def _stark_extension_name() -> str:
    digest = hashlib.sha1((_stark_strip_anchor_markers(CUDA_CPP_SRC) + _stark_strip_anchor_markers(CUDA_CU_SRC)).encode('utf-8')).hexdigest()[:12]
    return f'stark_cuda_l2_p71_{digest}'

def _stark_get_extension():
    global _STARK_EXTENSION
    if _STARK_EXTENSION is None:
        _STARK_EXTENSION = load_inline(
            name=_stark_extension_name(),
            cpp_sources=_stark_strip_anchor_markers(CUDA_CPP_SRC),
            cuda_sources=_stark_strip_anchor_markers(CUDA_CU_SRC),
            functions=None,
            extra_cflags=['-O3'],
            extra_cuda_cflags=['-O3', '--use_fast_math'],
            with_cuda=True,
            verbose=False,
        )
    return _STARK_EXTENSION

# <<<IMPROVE:user_helpers>>>
# <<<END_IMPROVE>>>

CUDA_CPP_SRC = r"""
# <<<IMPROVE:cuda_cpp>>>
#include <torch/extension.h>

torch::Tensor divide_leakyrelu_cuda(torch::Tensor x, double divisor);

torch::Tensor divide_leakyrelu(torch::Tensor x, double divisor) {
    if (x.is_cuda() && x.scalar_type() == at::kFloat && x.is_contiguous()) {
        return divide_leakyrelu_cuda(x, divisor);
    }
    auto y = x / divisor;
    return at::leaky_relu(y, 0.01);
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("divide_leakyrelu", &divide_leakyrelu, "Fused divide + leaky_relu (CUDA)");
}
# <<<END_IMPROVE>>>
"""

CUDA_CU_SRC = r"""
# <<<IMPROVE:cuda_cu>>>
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void divide_leakyrelu_scalar_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    float inv_divisor,
    int64_t n
) {
    int64_t idx = (int64_t)blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < n) {
        float v = __ldg(&input[idx]) * inv_divisor;
        output[idx] = v >= 0.0f ? v : 0.01f * v;
    }
}

__global__ void divide_leakyrelu_vec4_kernel(
    const float4* __restrict__ input,
    float4* __restrict__ output,
    float inv_divisor,
    int64_t n4
) {
    int64_t idx = (int64_t)blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < n4) {
        float4 v = __ldg(&input[idx]);
        float x0 = v.x * inv_divisor;
        float x1 = v.y * inv_divisor;
        float x2 = v.z * inv_divisor;
        float x3 = v.w * inv_divisor;
        v.x = x0>= 0.0f ? x0 : 0.01f * x0;
        v.y = x1 >= 0.0f ? x1 : 0.01f * x1;
        v.z = x2 >= 0.0f ? x2 : 0.01f * x2;
        v.w = x3 >= 0.0f ? x3 : 0.01f * x3;
        output[idx] = v;
    }
}

torch::Tensor divide_leakyrelu_cuda(torch::Tensor x, double divisor) {
    auto out = torch::empty_like(x);
    int64_t n = x.numel();
    float inv_divisor = 1.0f / static_cast<float>(divisor);
    const int block = 256;
    if (n % 4 == 0) {
        int64_t n4 = n / 4;
        int grid = (int)((n4 + block - 1) / block);
        divide_leakyrelu_vec4_kernel<<<grid, block>>>(
            reinterpret_cast<const float4*>(x.data_ptr<float>()),
            reinterpret_cast<float4*>(out.data_ptr<float>()),
            inv_divisor, n4
        );
    } else {
        int grid = (int)((n + block - 1) / block);
        divide_leakyrelu_scalar_kernel<<<grid, block>>>(
            x.data_ptr<float>(), out.data_ptr<float>(), inv_divisor, n
        );
    }
    return out;
}
# <<<END_IMPROVE>>>
"""

class ModelNew(nn.Module):
    """
        Simple model that performs a convolution, divides by a constant, and applies LeakyReLU.
        """
    def __init__(self, in_channels, out_channels, kernel_size, divisor):
        super().__init__()
        # <<<IMPROVE:init_body>>>
        self.conv = nn.Conv2d(in_channels, out_channels, kernel_size)
        self.divisor = divisor
        # <<<END_IMPROVE>>>

    def forward(self, x):
        # <<<IMPROVE:forward_stmt_1>>>
        # Baseline fallback keeps the official PyTorch forward path.
        # After implementing CUDA_CPP_SRC / CUDA_CU_SRC, call _stark_get_extension().your_entrypoint(...).
        x = self.conv(x)
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_2>>>
        if x.is_cuda:
            x = _stark_get_extension().divide_leakyrelu(x, float(self.divisor))
        else:
            x = x / self.divisor
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_3>>>
        if not x.is_cuda:
            x = torch.nn.functional.leaky_relu(x, negative_slope=0.01)
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_4>>>
        return x
        # <<<END_IMPROVE>>>

