) {
    if (x.is_cuda() && x.scalar_type() == at::kFloat) {
        // Run conv without bias; fuse bias+divide+leakyrelu in one epilogue pass
        c10::optional<at::Tensor> no_bias;
        torch::Tensor y = at::conv2d(
            x,
            weight,
            no_bias,
            {stride_h, stride_w},
            {pad_h, pad_w},
            {dil_h, dil_w},
            groups
        );
        if (y.is_contiguous()) {
            if (bias.defined() && bias.numel() > 0) {
