// Each block row handles one (n,c) slice; bias scalar loaded once per row.
__global__ void bias_divide_leakyrelu_2d_kernel(
    float* __restrict__ data,
    const float* __restrict__ bias,
    float inv_div,
    int64_t spatial,
    int64_t C
) {
    int64_t row = (int64_t)blockIdx.x;  // index into N*C rows
    int64_t c = row % C;
    float b = bias[c] * inv_div;        // pre-scale bias once
    float* base = data + row * spatial;

    for (int64_t s = (int64_t)blockIdx.y * blockDim.x + threadIdx.x;
         s < spatial;
         s += (int64_t)gridDim.y * blockDim.x) {
        float v = base[s] * inv_div + b;
        base[s] = (v >= 0.0f) ? v : (0.01f * v);
    }
}

__global__ void divide_leakyrelu_kernel(
    float* __restrict__ data,
    float inv_div,
    int64_t n
) {
    int64_t idx = (int64_t)blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < n) {
        float v = data[idx] * inv_div;
        data[idx] = (v >= 0.0f) ? v : (0.01f * v);
    }
